package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.client.RestClient;import org.springframework.test.web.client.MockRestServiceServer;import static org.springframework.test.web.client.response.MockRestResponseCreators.*;import org.springframework.http.MediaType;import org.springframework.web.server.ResponseStatusException;
class LearningRoadmapClientTest {
 UUID space,link,actor,source,id;String trace="00-"+"a".repeat(32)+"-"+"b".repeat(16)+"-01";String key="c".repeat(43);MockRestServiceServer server;LearningRoadmapClient client;
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();link=ids.next();actor=ids.next();source=ids.next();id=ids.next();var builder=RestClient.builder().baseUrl("https://learning.invalid");server=MockRestServiceServer.bindTo(builder).build();client=new LearningRoadmapClient(builder.build(),key);}
 String response(){return "{\"principalId\":\""+actor+"\",\"spaceId\":\""+space+"\",\"roadmapLinkId\":\""+link+"\",\"version\":1,\"state\":\"ACTIVE\",\"sourceSpaceId\":\""+source+"\",\"sourceRoadmapId\":\""+id+"\",\"sourceVersion\":1,\"title\":\"Source\"}";}
 @Test void dedicatedCapabilityCarriesTraceWithoutBrowserCookies(){server.expect(request->{assertEquals("/internal/learning/group-roadmap-reference",request.getURI().getPath());assertEquals("Bearer "+key,request.getHeaders().getFirst("Authorization"));assertEquals(trace,request.getHeaders().getFirst("traceparent"));assertNull(request.getHeaders().getFirst("Cookie"));assertNull(request.getHeaders().getFirst("Origin"));}).andRespond(withSuccess(response(),MediaType.APPLICATION_JSON));assertEquals(link,client.check(space,link,actor,1,"d".repeat(43),trace).roadmapLinkId());server.verify();}
 @Test void changedStateVersionForeignScopeAndBadBodiesFailClosed(){for(String body:List.of(response().replace("ACTIVE","RETIRED"),response().replace("\"version\":1","\"version\":2"),response().replace(space.toString(),source.toString()),response()+" {}","{",response().replace("\"version\":1","\"version\":1.5")," ".repeat(16385))){server.reset();server.expect(request->{}).andRespond(withSuccess(body,MediaType.APPLICATION_JSON));assertThrows(ResponseStatusException.class,()->client.check(space,link,actor,1,"d".repeat(43),trace));server.verify();}}
 @Test void foreignPrincipalAndMissingFieldsAreNotAccepted(){server.expect(request->{}).andRespond(withSuccess(response().replace(actor.toString(),source.toString()),MediaType.APPLICATION_JSON));assertEquals(503,assertThrows(ResponseStatusException.class,()->client.check(space,link,actor,1,"d".repeat(43),trace)).getStatusCode().value());}
}
